async function loadHistoryData(agent) {
    const data = await fetchData(`/trades/history?agent=${agent}`);
    if (!data) return;

    document.getElementById('modalHistoryTrades').textContent = data.total_trades || 0;
    document.getElementById('modalHistoryWins').textContent = data.winning_trades || 0;
    document.getElementById('modalHistoryLosses').textContent = data.losing_trades || 0;
    document.getElementById('modalHistoryWinrate').textContent = (data.winrate || 0).toFixed(0) + '%';

    const pnl = data.total_pnl_usdt || 0;
    const pnlEl = document.getElementById('modalHistoryPnl');
    pnlEl.textContent = (pnl >= 0 ? '+' : '') + '$' + pnl.toFixed(2);
    pnlEl.className = pnl >= 0 ? 'font-bold pnl-positive' : 'font-bold pnl-negative';

    const list = document.getElementById('modalHistoryList');
    if (!data.trades || data.trades.length === 0) {
        list.innerHTML = '<div class="text-dim text-sm text-center py-4">No trades yet</div>';
        return;
    }

    list.innerHTML = data.trades.slice(0, 20).map(t => {
        const pnlClass = t.pnl_usdt >= 0 ? 'pnl-positive' : 'pnl-negative';
        const reason = t.close_reason === 'stop_loss' ? 'SL' :
                      t.close_reason === 'take_profit' ? 'TP' : 'M';
        return `
            <div class="trade-row">
                <div>
                    <div class="font-semibold">${t.symbol}</div>
                    <div class="text-xs text-dim">${t.side}</div>
                </div>
                <div class="${pnlClass} text-right">$${t.pnl_usdt.toFixed(2)}</div>
                <div class="text-center">
                    <span class="badge ${reason === 'SL' ? 'badge-red' : reason === 'TP' ? 'badge-green' : 'badge-gray'}">${reason}</span>
                </div>
                <div class="text-center">
                    <span class="badge badge-gray">${t.grade || '-'}</span>
                </div>
            </div>
        `;
    }).join('');
}

async function loadLearningData(agent) {
    const data = await fetchData(`/learning/${agent}`);
    if (!data) return;

    document.getElementById('modalLearningLevel').textContent = data.level || 1;
    document.getElementById('modalLearningXp').textContent = data.xp || 0;
    document.getElementById('modalLearningXpNext').textContent = (data.xp || 0) + (data.xp_to_next_level || 100);

    const xpPct = data.xp_to_next_level > 0 ?
        (data.xp / ((data.xp || 0) + (data.xp_to_next_level || 100))) * 100 : 0;
    document.getElementById('modalLearningXpBar').style.width = xpPct + '%';

    // Next level benefits
    const benefits = data.next_level_benefits || {};
    if (Object.keys(benefits).length > 0) {
        document.getElementById('modalNextBenefits').innerHTML = `
            <div class="grid grid-cols-2 gap-2 text-sm">
                <div><span class="text-dim">Max Leverage:</span> ${benefits.max_leverage || '-'}x</div>
                <div><span class="text-dim">Max Positions:</span> ${benefits.max_positions || '-'}</div>
                <div><span class="text-dim">Max Risk:</span> ${benefits.max_risk_pct || '-'}%</div>
            </div>
        `;
    }

    // Worst pairs
    const worstPairs = data.worst_pairs || [];
    document.getElementById('modalWorstPairs').innerHTML = worstPairs.length > 0 ?
        worstPairs.map(p => `
            <div class="flex justify-between py-1">
                <span>${p.symbol}</span>
                <span class="pnl-negative">$${p.pnl_usdt?.toFixed(2) || '0.00'}</span>
